function compute(inputs) {
  const eta = inputs.eta;
  const x0 = inputs.x0;
  const steps = 20;
  const xs = [x0];
  const losses = [x0*x0];
  let x = x0;
  for (let i = 0; i < steps; i++) {
    const grad = 2 * x;
    x = x - eta * grad;
    xs.push(x);
    losses.push(x*x);
  }
  const table = {
    columns: ["Step", "x", "f(x)"],
    rows: xs.map((val, i) => [i, val, losses[i]])
  };
  const series = {
    x: Array.from({length: steps+1}, (_, i) => i),
    lines: [
      { name: "x", y: xs },
      { name: "f(x)", y: losses }
    ],
    marker: { x: 0, y: x0 }
  };
  const finalX = xs[steps];
  const finalLoss = losses[steps];
  let insight = "";
  if (eta < 1) {
    insight = `Converges to 0. Final loss = ${finalLoss.toExponential(2)}.`;
  } else if (eta === 1) {
    insight = "Oscillates between x0 and -x0. Loss stays constant.";
  } else {
    insight = `Diverges. Final |x| = ${Math.abs(finalX).toExponential(2)}.`;
  }
  return {
    series: series,
    table: table,
    finalX: finalX,
    finalLoss: finalLoss,
    insight: insight
  };
}
